WITH parsed AS (SELECT id, plan, currency, tier_limits, tier_prices, ARRAY_MIN(tier_prices) AS lowest_price, AGGREGATE(tier_prices, 0D, (acc, p) -> acc + p, acc -> ROUND(acc / SIZE(tier_prices), 2)) AS avg_tier_price FROM price_tiers WHERE currency = 'THB') SELECT CASE WHEN avg_tier_price >= 26 THEN 'LARGE' ELSE 'SMALL' END AS avg_tier_price_tier, PERCENTILE_APPROX(lowest_price, ARRAY(0.25, 0.5, 0.75)) AS lowest_price_quartiles, COUNT(DISTINCT currency) AS distinct_currencies, COUNT(*) AS row_count FROM parsed GROUP BY CASE WHEN avg_tier_price >= 26 THEN 'LARGE' ELSE 'SMALL' END ORDER BY distinct_currencies NULLS LAST;
